        size_t i;
        const cdf_directory_t *d;

        *root = NULL;
        for (i = 0; i < dir->dir_len; i++)
                if (dir->dir_tab[i].d_type == CDF_DIR_TYPE_ROOT_STORAGE)
                        break;

