private int
cdf_file_catalog(struct magic_set *ms, const cdf_header_t *h,
    const cdf_stream_t *sst)
{
        cdf_catalog_t *cat;
        size_t i;
        char buf[256];
        cdf_catalog_entry_t *ce;

        if (NOTMIME(ms)) {
                if (file_printf(ms, "Microsoft Thumbs.db [") == -1)
                        return -1;
                if (cdf_unpack_catalog(h, sst, &cat) == -1)
                        return -1;
                ce = cat->cat_e;
                /* skip first entry since it has a , or paren */
                for (i = 1; i < cat->cat_num; i++)
                        if (file_printf(ms, "%s%s",
                            cdf_u16tos8(buf, ce[i].ce_namlen, ce[i].ce_name),
                            i == cat->cat_num - 1 ? "]" : ", ") == -1) {
                                free(cat);
                                return -1;
                        }
                free(cat);
        } else if (ms->flags & MAGIC_MIME_TYPE) {
                if (file_printf(ms, "application/CDFV2") == -1)
                        return -1;
        }
        return 1;
}

private int
cdf_file_summary_info(struct magic_set *ms, const cdf_header_t *h,
    const cdf_stream_t *sst, const cdf_directory_t *root_storage)
{
        cdf_summary_info_header_t si;
        cdf_property_info_t *info;
        size_t count;
        int m;

        if (cdf_unpack_summary_info(sst, h, &si, &info, &count) == -1)
                return -1;

        if (NOTMIME(ms)) {
                const char *str;

                if (file_printf(ms, "Composite Document File V2 Document")
                    == -1)
                        return -1;

                if (file_printf(ms, ", %s Endian",
                    si.si_byte_order == 0xfffe ?  "Little" : "Big") == -1)
                        return -2;
                switch (si.si_os) {
                case 2:
                        if (file_printf(ms, ", Os: Windows, Version %d.%d",
                            si.si_os_version & 0xff,
                            CAST(uint32_t, si.si_os_version) >> 8) == -1)
                                return -2;
                        break;
                case 1:
                        if (file_printf(ms, ", Os: MacOS, Version %d.%d",
                            CAST(uint32_t, si.si_os_version) >> 8,
                            si.si_os_version & 0xff) == -1)
                                return -2;
                        break;
                default:
                        if (file_printf(ms, ", Os %d, Version: %d.%d", si.si_os,
                            si.si_os_version & 0xff,
                            CAST(uint32_t, si.si_os_version) >> 8) == -1)
                                return -2;
                        break;
                }
                if (root_storage) {
                        str = cdf_clsid_to_mime(root_storage->d_storage_uuid,
                            clsid2desc);
                        if (str) {
                                if (file_printf(ms, ", %s", str) == -1)
                                        return -2;
                        }
                }
        }

        m = cdf_file_property_info(ms, info, count, root_storage);
        free(info);

        return m == -1 ? -2 : m;
}

